 const bin=process.env.JUANERAI_TOOLCHAIN_BIN;assert.ok(bin);const deadlines=createControlledDeadlineScheduler(),dtos:any[]=[];let credentials=0;
 const store=createLocalDesktopDecisionCaseStore({projectRoot,assertCompleted:(...a:Parameters<ReturnType<typeof createPiProfessionalAgent>['assertCompleted']>)=>agent.assertCompleted(...a)}),agent=createPiProfessionalAgent({projectRoot,analysisModel:'mimo-v2.6-flash',authorizeWork:(id,phase)=>store.authorizesProfessionalWork(id,phase),credentials:{withCredential:async(p,run)=>{credentials++;return offlineCredentials.withCredential(p,run);}},fetch:async(url,init)=>{const dto=JSON.parse(String(init!.body));dtos.push(dto);if(reply)return reply(url,init);const sent=dto.messages.some((m:any)=>m.role==='assistant'&&(m.tool_calls??[]).some((c:any)=>c.function.name==='propose_professional_draft'));if(sent)return offlineResponse(dtos.length,[],'MODEL专业草稿等待人工审阅。');const payload=dto.messages.filter((m:any)=>m.role==='user'&&typeof m.content==='string').flatMap((m:any)=>{try{return [JSON.parse(m.content)];}catch{return [];}}).findLast((v:any)=>v.schema_version==='1.0'&&v.action_kind),content=payload.action_kind==='organize_question'?{question_text:'合成候选问题',hypothesis_display_title:'待核对',business_context:'仅当前获准资料',alternative_explanations:['关联不能证明因果']}:payload.action_kind==='explain_evidence'?{evidence_explanation_text:'合成有限观察，不能认证因果。'}:{candidates:['小范围核对','保留既有方案'].map(title=>({title,evidence_basis:payload.accepted_finding.finding_id,risk_or_refutation:'关联不能证明因果',applicability_conditions:'仅当前合成资料',future_validation_metric:'复购率'}))};return offlineResponse(dtos.length,[{name:'propose_professional_draft',args:content}]);}}),runEvidenceStore=createLocalDesktopRunEvidenceStore({projectRoot}),analysisExecution=createDuckDbPythonDesktopLocalAnalysisExecution({duckdbExecutable:join(bin,'duckdb'),duckdbVersion:'1.5.2',...readDesktopPythonTool(bin)}),application=createXanthilDesktopDecisionCaseApplication({store,agent,runEvidenceStore,analysisExecution,clock:fixedClock,deadlineScheduler:deadlines.scheduler});
